r"""$\mathcal{G}$ is called a generator if $\sigma(\mathcal{G}) = \mathcal{A}$, this also means $\Omega \in \mathcal{G}$"""

import json

record_id = "mse_1645967__ans1646288"
verdict = "CONFIRMED"
notes = ("The witness is valid. Independently intersecting all sigma-algebras "
         "on Ω = {0, 1} that contain G = {{0}} yields P(Ω), while Ω is not "
         "in G. The refuted statement is substantive, not plainly a typo: "
         "it confuses membership in the generating family with membership in "
         "the sigma-algebra generated by that family.")

omega = frozenset((0, 1))
empty = frozenset()
singleton_zero = frozenset((0,))
power_set = (
    empty,
    singleton_zero,
    frozenset((1,)),
    omega,
)
generators = frozenset((singleton_zero,))

def is_sigma_algebra(candidate):
    if empty not in candidate or omega not in candidate:
        return False
    for event in candidate:
        if omega.difference(event) not in candidate:
            return False
    for left in candidate:
        for right in candidate:
            if left.union(right) not in candidate:
                return False
    return True

containing_sigma_algebras = []
for mask in range(1 << len(power_set)):
    candidate = frozenset(
        power_set[index]
        for index in range(len(power_set))
        if mask & (1 << index)
    )
    if generators.issubset(candidate) and is_sigma_algebra(candidate):
        containing_sigma_algebras.append(candidate)

assert containing_sigma_algebras
generated = containing_sigma_algebras[0]
for candidate in containing_sigma_algebras[1:]:
    generated = generated.intersection(candidate)

assert generated == frozenset(power_set)
assert omega not in generators

print(json.dumps({
    "record_id": record_id,
    "verdict": verdict,
    "notes": notes,
}, ensure_ascii=False, separators=(",", ":")))
